-- Conserva zonas, camas, plano, nodos y umbrales. Lote de referencia: RSC-2026-014.
SET client_encoding = 'UTF8';
SET synchronous_commit = off;
TRUNCATE ventas.despacho_item, ventas.despacho, ventas.orden_item, ventas.orden, ventas.cliente,
         calidad.tratamiento, calidad.incidencia, calidad.inspeccion,
         produccion.cosecha, produccion.labor, produccion.siembra, monitoreo.lectura RESTART IDENTITY;
DELETE FROM produccion.lote WHERE id <> 1;

UPDATE finca.zona SET nombre = v.nombre, descripcion = v.descr, hectareas = v.ha, actualizado_por = 'diseno' FROM (VALUES
  ('A', 'Zona A · Ladera alta', 'Plantación 2019, 9 camas de 30 m² bajo polisombra 70 %. Suelo franco-arcilloso, buen drenaje.', 0.08),
  ('B', 'Zona B · Terraza media', 'Plantación 2020, 8 camas; zona más húmeda, susceptible a hongos en temporada de lluvias.', 0.06),
  ('C', 'Zona C · Ampliación baja', 'Ampliación 2021, 8 camas; mayor temperatura por menor altitud y exposición oeste.', 0.06)
) AS v(codigo, nombre, descr, ha) WHERE zona.codigo = v.codigo;
