(463, 7, 58, 'enfermedad', 'Antracnosis (Colletotrichum gloeosporioides)', 'baja', 'resuelta', '2026-11-19', 'Hallazgo en trampa/lupa durante inspección de rutina. Foco en 4 % de la cama.', 'calidad', '2026-11-19 09:30:00-05', '2026-11-27 16:00:00-05'),
(464, 22, 188, 'plaga', 'Babosas y caracoles (Deroceras sp.)', 'media', 'en_tratamiento', '2026-11-20', 'Reportada por el operario durante el corte; confirmada por MIPE. Foco en 11 % de la cama.', 'calidad', '2026-11-20 09:30:00-05', '2026-11-20 09:30:00-05'),
(465, 8, 67, 'plaga', 'Babosas y caracoles (Deroceras sp.)', 'baja', 'abierta', '2026-11-25', 'Reportada por el operario durante el corte; confirmada por MIPE. Foco en 14 % de la cama.', 'calidad', '2026-11-25 09:30:00-05', '2026-11-25 09:30:00-05'),
